or:#bd2e3b;border-color:#efc5ca}.sb-note-actions details[open]{flex:1 0 100%}.sb-note-actions details form{display:grid;gap:7px;margin-top:7px}.sb-note-actions textarea{width:100%;min-height:80px;padding:9px;border:1px solid #cad8e8;border-radius:8px}.sb-note-actions details button{min-height:36px;border:0;border-radius:7px;background:#1764c0;color:#fff;font-size:11px;font-weight:850}.tema-koyu .sb-note-flow{background:#202f49;border-color:#41526e}.tema-koyu .sb-note-flow h3,.tema-koyu .sb-note-history p{color:#edf4ff}@media(max-width:520px){.sb-note-flow header{align-items:flex-start;flex-direction:column}.sb-note-history article{grid-template-columns:1fr}.sb-note-history article>span{justify-self:start}.sb-note-actions{flex-wrap:wrap}}
