<script>
document.addEventListener('DOMContentLoaded',()=>{
  const input=document.getElementById('sb-camera'),form=document.getElementById('sb-photo-form'),submit=document.getElementById('sb-photo-submit'),status=document.getElementById('sb-photo-status');
  if(!input||!form||!submit||!status)return;
  let hazirlaniyor=false;
  const durum=(metin,sinif='')=>{status.textContent=metin;status.className='sb-photo-status '+sinif};
  const resimYukle=file=>new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(url);resolve(img)};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Fotoğraf açılamadı'))};img.src=url});
  input.addEventListener('change',async()=>{
    const file=input.files?.[0];if(!file)return;
    hazirlaniyor=true;submit.disabled=true;durum('Fotoğraf yükleme için hazırlanıyor…','is-working');
    try{
      const img=await resimYukle(file),oran=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');
      canvas.width=Math.max(1,Math.round(img.naturalWidth*oran));canvas.height=Math.max(1,Math.round(img.naturalHeight*oran));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);
      let kalite=.82,blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',kalite));
      while(blob&&blob.size>850000&&kalite>.48){kalite-=.08;blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',kalite))}
      if(!blob)throw new Error('Fotoğraf dönüştürülemedi');
      const dt=new DataTransfer(),ad=(file.name.replace(/\.[^.]+$/,'')||'servis-fotografi')+'.jpg';dt.items.add(new File([blob],ad,{type:'image/jpeg',lastModified:Date.now()}));input.files=dt.files;
      durum('Fotoğraf hazır · '+Math.max(1,Math.round(blob.size/1024))+' KB','is-ready');
    }catch(e){durum('Fotoğraf küçültülemedi; farklı bir fotoğraf deneyin.','is-error');input.value=''}finally{hazirlaniyor=false;submit.disabled=false}
  });
  form.addEventListener('submit',e=>{if(hazirlaniyor||!input.files?.length){e.preventDefault();durum(hazirlaniyor?'Fotoğraf hazırlanıyor, lütfen bekleyin.':'Önce fotoğraf çekin.','is-error')}});
});
</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const liste=document.querySelector('[data-panel="bakim"] .sb-maintenance');if(liste&&!liste.querySelector('[data-bakim="iscilik"]'))liste.insertAdjacentHTML('beforeend','<button type="button" data-bakim="iscilik">İşçilik</button>')});</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const tabs=document.querySelectorAll('[data-view]'),panels=document.querySelectorAll('[data-panel]'),reminder=document.getElementById('sb-reminder-card'),bakimPanel=document.querySelector('[data-panel="bakim"]'),storageKey='izgios-servis-sekme-{{$servis->id}}';const sekmeAc=(ad,kaydet=true)=>{const tab=[...tabs].find(x=>x.dataset.view===ad)||tabs[0];tabs.forEach(x=>x.classList.toggle('active',x===tab));panels.forEach(x=>x.classList.toggle('active',x.dataset.panel===tab.dataset.view));if(kaydet)sessionStorage.setItem(storageKey,tab.dataset.view)};if(reminder&&bakimPanel){bakimPanel.prepend(reminder);reminder.style.display='block'}tabs.forEach(t=>t.onclick=()=>sekmeAc(t.dataset.view));sekmeAc(sessionStorage.getItem(storageKey)||'islem',false);document.querySelectorAll('[data-panel] form').forEach(form=>form.addEventListener('submit',()=>sessionStorage.setItem(storageKey,form.closest('[data-panel]')?.dataset.panel||'islem')));const cam=document.getElementById('sb-camera'),camBtn=document.getElementById('sb-camera-button');camBtn?.addEventListener('click',()=>cam.click());const title=document.getElementById('sb-bakim-title'),input=document.querySelector('[name="bakim_turu"]');document.querySelectorAll('[data-bakim]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-bakim]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');input.value=b.dataset.bakim;title.textContent=b.textContent+' bakımı'});});</script>
